import {
  ArgumentParserError,
  parseArguments,
  renderError,
  renderHelp,
} from './lib/argparse_compat.mjs';
import { getProgramName } from './lib/program_name.mjs';
import { runReferenceValidator } from './lib/reference_validator.mjs';

export function main(argv = process.argv) {
  const programName = getProgramName(argv);
  let parsedArguments;

  try {
    parsedArguments = parseArguments(argv.slice(2));
  } catch (error) {
    if (error instanceof ArgumentParserError) {
      process.stderr.write(renderError(programName, error.message));
      process.exitCode = 2;
      return;
    }

    throw error;
  }

  if (parsedArguments.helpRequested) {
    process.stdout.write(renderHelp(programName));
    return;
  }

  const status = runReferenceValidator({
    instanceJson: parsedArguments.values.a,
    schemaJson: parsedArguments.values.b,
  });

  if (status !== 0) {
    process.exitCode = status;
  }
}

main();

