const NEGATIVE_NUMBER_PATTERN = /^-(?:\d+|\d+\.\d+|\.\d+)$/;
const LONG_OPTIONS = ['--help', '--a', '--b'];

export class ArgumentParserError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentParserError';
  }
}

export function renderHelp(programName) {
  return (
    `usage: ${programName} [-h] --a A --b B\n` +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A       instance data (JSON string)\n' +
    '  --b B       schema (JSON string)\n'
  );
}

export function renderError(programName, message) {
  return `usage: ${programName} [-h] --a A --b B\n${programName}: error: ${message}\n`;
}

export function parseArguments(argv) {
  const values = { a: undefined, b: undefined };
  const extras = [];
  let helpRequested = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const optionToken = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const attachedValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);
      const resolvedOption = resolveLongOption(optionToken);

      if (resolvedOption === '--help') {
        if (attachedValue !== null) {
          throw new ArgumentParserError(
            `argument -h/--help: ignored explicit argument '${attachedValue}'`,
          );
        }

        helpRequested = true;
        continue;
      }

      if (resolvedOption === '--a' || resolvedOption === '--b') {
        const key = resolvedOption.slice(2);

        if (attachedValue !== null) {
          values[key] = attachedValue;
          continue;
        }

        const nextToken = argv[index + 1];

        if (nextToken === undefined || isOptionLike(nextToken)) {
          throw new ArgumentParserError(`argument ${resolvedOption}: expected one argument`);
        }

        values[key] = nextToken;
        index += 1;
        continue;
      }

      extras.push(token);
      continue;
    }

    if (token.startsWith('-') && token !== '-') {
      if (token.startsWith('-h=')) {
        throw new ArgumentParserError(
          `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
        );
      }

      if (token === '-h' || /^-h[^=].*$/.test(token)) {
        helpRequested = true;
        continue;
      }

      extras.push(token);
      continue;
    }

    extras.push(token);
  }

  if (helpRequested) {
    return { helpRequested: true, values };
  }

  const missing = [];

  if (values.a === undefined) {
    missing.push('--a');
  }

  if (values.b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    throw new ArgumentParserError(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    throw new ArgumentParserError(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return { helpRequested: false, values };
}

function isOptionLike(token) {
  return token.startsWith('-') && token !== '-' && !NEGATIVE_NUMBER_PATTERN.test(token);
}

function resolveLongOption(token) {
  const matches = LONG_OPTIONS.filter((option) => option.startsWith(token));

  return matches.length === 1 ? matches[0] : null;
}

