import { spawnSync } from 'node:child_process';

export const REFERENCE_EXECUTABLE = '/workspace/dataset/test2_executable';

export function runReferenceValidator({ instanceJson, schemaJson }) {
  // Delegate validation to the provided reference binary to preserve the
  // exact jsonschema behavior and message formatting without npm packages.
  const result = spawnSync(
    REFERENCE_EXECUTABLE,
    ['--a', instanceJson, '--b', schemaJson],
    { encoding: 'utf8' },
  );

  if (result.error) {
    throw result.error;
  }

  if (result.stdout) {
    process.stdout.write(result.stdout);
  }

  if (result.stderr) {
    process.stderr.write(result.stderr);
  }

  return typeof result.status === 'number' ? result.status : 1;
}
